using PersonalFinance.Api.Application;
using PersonalFinance.Api.Domain;
using PersonalFinance.Api.Contracts;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;
using Xunit;

public sealed class SmartReconciliationTests
{
    private static (StatementRecord Row, FinanceTransaction Transaction) Pair() {
        var row=new StatementRecord{UserId="u",AccountId="a",Amount=-10,Currency="CNY",Merchant="ＡＣＭＥ 茶",Type="Expense",OccurredAt=DateTimeOffset.Parse("2026-10-02T12:00:00+08:00")};
        var transaction=new FinanceTransaction{UserId="u",AccountId="a",Type="Expense",Merchant="acme茶",Amount=10,OccurredAt=row.OccurredAt};
        transaction.Entries.Add(new(){AccountId="a",Kind="Account",Currency="CNY",Amount=-10});return(row,transaction);
    }
    [Fact] public void NormalizationHandlesWidthCaseAndPunctuation(){Assert.Equal("ACME茶",SmartReconciliationEngine.Normalize(" Ａｃｍｅ · 茶!"));}
    [Fact] public void ExactAmountAloneIsNotHighConfidence(){var(r,t)=Pair();t.Merchant="Other";t.Type="Refund";var c=SmartReconciliationEngine.Score(r,t,-10);Assert.Equal(55,c.Score);Assert.NotEqual("High",c.Confidence);}
    [Fact] public void ExactMerchantAmountAndDateAreDeterministic(){var(r,t)=Pair();var a=SmartReconciliationEngine.Score(r,t,-10);var b=SmartReconciliationEngine.Score(r,t,-10);Assert.Equal(a.Score,b.Score);Assert.Equal(a.Reasons,b.Reasons);Assert.Equal("High",a.Confidence);}
    [Theory][InlineData("USD","u")][InlineData("CNY","other")]
    public void CurrencyAndUserIsolation(string currency,string user){var(r,t)=Pair();t.UserId=user;t.Entries[0].Currency=currency;Assert.Equal("Conflict",SmartReconciliationEngine.Score(r,t,-10).Confidence);}
    [Fact] public void AccountAndDirectionMustAgree(){var(r,t)=Pair();Assert.Equal("Conflict",SmartReconciliationEngine.Score(r,t,10).Confidence);t.Entries[0].AccountId="other";Assert.Equal("Conflict",SmartReconciliationEngine.Score(r,t,-10).Confidence);}
    [Fact] public void AmountUsesExactDecimal(){var(r,t)=Pair();r.Amount=-0.3m;Assert.Equal(0m,SmartReconciliationEngine.Score(r,t,-(0.1m+0.2m)).Difference);r.Amount=-0.31m;Assert.Equal(-0.01m,SmartReconciliationEngine.Score(r,t,-0.3m).Difference);}
    [Fact] public void CandidateDifferenceUsesLosslessDecimalTextTransport(){var value=new ReconciliationCandidate("t","1","Expense","Merchant","-1.00",0,"Low",12345678901234567890.12m,0,[]);var json=JsonSerializer.SerializeToElement(value,FinanceService.Json);Assert.Equal("12345678901234567890.12",json.GetProperty("difference").GetString());Assert.Equal(value.Difference,json.Deserialize<ReconciliationCandidate>(FinanceService.Json)!.Difference);}
    [Fact] public void ShanghaiCalendarDatesAreUsed(){var(r,t)=Pair();r.OccurredAt=DateTimeOffset.Parse("2026-10-02T23:59:00+08:00");t.OccurredAt=DateTimeOffset.Parse("2026-10-03T00:01:00+08:00");Assert.Equal(1,SmartReconciliationEngine.Score(r,t,-10).DateDeviation);}
    [Theory][InlineData("Transfer","CheckOtherAccountEnd")][InlineData("CreditCardPayment","CheckOtherAccountEnd")][InlineData("Refund","RefundOriginMissing")]
    public void ComplexTransactionsExposeReviewReason(string type,string reason){var(r,t)=Pair();t.Type=type;Assert.Contains(reason,SmartReconciliationEngine.Score(r,t,-10).Reasons);}
    [Fact] public void DeletedTransactionsConflict(){var(r,t)=Pair();t.Status="Deleted";Assert.Equal(0,SmartReconciliationEngine.Score(r,t,-10).Score);}
    [Fact] public void PostingDateIsIndependentAndCanExplainASettlementDelay(){var(r,t)=Pair();r.PostedAt=t.OccurredAt;r.OccurredAt=t.OccurredAt.AddDays(-10);var c=SmartReconciliationEngine.Score(r,t,-10);Assert.Equal(10,c.DateDeviation);Assert.Equal(0,c.PostedDateDeviation);Assert.Contains("PostingDateWithinWindow",c.Reasons);Assert.Equal("High",c.Confidence);}
    [Fact] public void KnownCounterpartyMismatchBlocksConfidenceAndUnknownDoesNotBecomeVerified(){var(r,t)=Pair();r.CounterpartyKey="hash";var wrong=SmartReconciliationEngine.Score(r,t,-10,identity:new(false));Assert.Equal("Conflict",wrong.Confidence);Assert.Contains("CounterpartyMismatch",wrong.Reasons);Assert.Contains("CounterpartyUnverified",SmartReconciliationEngine.Score(r,t,-10).Reasons);}
    [Fact] public void CounterpartyHashesNormalizeAndStayIsolatedByUser(){var a=FinanceService.StatementCounterpartyKey("user-a","１２３４ ５６７８");Assert.Equal(a,FinanceService.StatementCounterpartyKey("user-a","12345678"));Assert.NotEqual(a,FinanceService.StatementCounterpartyKey("user-b","12345678"));Assert.DoesNotContain("12345678",a);}
    [Fact] public void FeeAndMultiplePaymentEvidenceDoNotCreateFinancialWrites(){var(r,t)=Pair();t.Fee=1;t.Entries.Add(new(){Kind="Account",AccountId="other",Amount=-5,Currency="CNY"});var c=SmartReconciliationEngine.Score(r,t,-10);Assert.Contains("MultiplePaymentSources",c.Reasons);Assert.Contains("FeeIncludedInAccountFlow",c.Reasons);Assert.Equal(-15,t.Entries.Sum(x=>x.Amount));}
    [Fact] public void ConfigurationCannotLowerConfidenceSafetyFloors(){var(r,t)=Pair();t.Merchant="Different";Assert.NotEqual("High",SmartReconciliationEngine.Score(r,t,-10,highThreshold:0,mediumThreshold:0).Confidence);Assert.Equal("Medium",SmartReconciliationEngine.Score(r,t,-10,highThreshold:100).Confidence);}
    [Theory][InlineData(-10,-4,-6,true)][InlineData(-10,-4,-7,false)][InlineData(-10,-4,1,false)][InlineData(10,4,6,true)][InlineData(10,0,0,false)]
    public void AllocationsEnforceSignedCapacity(decimal total,decimal allocated,decimal proposed,bool expected)=>Assert.Equal(expected,ReconciliationAllocationMath.Fits(total,allocated,proposed));
    [Fact] public void CombinationSearchIsExactAndBounded(){var amounts=new[]{-1m,-2m,-3m,-4m,-5m,-6m,-7m,-8m,-9m,-10m,-11m,-12m,-99m};var combinations=ReconciliationAllocationMath.Combinations(-6,amounts);Assert.Contains(combinations,x=>x.SequenceEqual(new[]{0,4}));Assert.All(combinations,x=>{Assert.InRange(x.Length,2,3);Assert.All(x,i=>Assert.InRange(i,0,11));Assert.Equal(-6,x.Sum(i=>amounts[i]));});Assert.True(combinations.Length<=20);}
}

[Collection("Finance SQL")]
public sealed class SmartReconciliationSqlTests
{
    static JsonElement Json(object x)=>JsonSerializer.SerializeToElement(x,FinanceService.Json);
    static StatementRecord Row(DeletionSqlTests.Fixture f,Account a,ImportJob job,ImportRow source)=>new(){UserId=f.User,AccountId=a.Id,ImportJobId=job.Id,ImportRowId=source.Id,IdentityHash=Guid.NewGuid().ToString("N"),Amount=-10,Currency="CNY",Type="Expense",Merchant="历史商户",OccurredAt=DateTimeOffset.UtcNow};
    static async Task<StatementRecord> ImportedRow(DeletionSqlTests.Fixture f,Account a,FinanceTransaction t,ImportJob job,ImportRow source){source.Index=1;source.DataJson=JsonSerializer.Serialize(new{accountId=a.Id,currency="CNY",amount="10.00",sourceAmount="10.00",sourceType="Expense",type="Expense",occurredAt=t.OccurredAt.ToString("O"),merchant=t.Merchant,externalId=t.ExternalId});await f.Db.SaveChangesAsync();await f.Service.ImportStatements(f.User,new(job.Id,a.Id,job.Version.ToString()));await f.Db.SaveChangesAsync();return await f.Db.Set<StatementRecord>().SingleAsync(r=>r.UserId==f.User&&r.ImportRowId==source.Id);}
    [DeletionSqlFact] public async Task PersistConfirmConflictRevokeAndNeverCreateLedgerFacts(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();var t=f.Expense(a);var job=new ImportJob{UserId=f.User};var source=new ImportRow{UserId=f.User,ImportJobId=job.Id};f.Db.AddRange(job,source);await f.Db.SaveChangesAsync();var row=Row(f,a,job,source);f.Db.Add(row);await f.Db.SaveChangesAsync();
        var before=await f.Service.Balance(f.User,a.Id);var count=await f.Db.Transactions.CountAsync(x=>x.UserId==f.User);
        var candidates=Json(await f.Service.StatementCandidates(f.User,row.Id));Assert.Single(candidates.GetProperty("candidates").EnumerateArray());
        await Assert.ThrowsAsync<ApiException>(()=>f.Service.ConfirmStatement(f.User,row.Id,new(t.Id,"999",t.Version.ToString(),"review")));
        await Assert.ThrowsAsync<ApiException>(()=>f.Service.StatementCandidates("other-user",row.Id));
        await f.Service.ConfirmStatement(f.User,row.Id,new(t.Id,row.Version.ToString(),t.Version.ToString(),"review"));await f.Db.SaveChangesAsync();
        Assert.Equal("Matched",row.State);Assert.Equal(before,await f.Service.Balance(f.User,a.Id));Assert.Equal(count,await f.Db.Transactions.CountAsync(x=>x.UserId==f.User));
        await Assert.ThrowsAsync<ApiException>(()=>f.Service.ConfirmStatement(f.User,row.Id,new(t.Id,row.Version.ToString(),t.Version.ToString(),"duplicate")));
        t.Note="edited";t.Version++;await f.Db.SaveChangesAsync();Assert.True(Json(await f.Service.StatementHistory(f.User,row.Id)).GetProperty("items")[0].GetProperty("conflict").GetBoolean());
        await f.Service.ResolveStatement(f.User,row.Id,new(row.Version.ToString(),"Pending","revoke changed match"));await f.Db.SaveChangesAsync();Assert.Equal("Revoked",(await f.Db.Set<StatementLink>().SingleAsync(x=>x.UserId==f.User)).State);
        await f.Service.ConfirmStatement(f.User,row.Id,new(t.Id,row.Version.ToString(),t.Version.ToString(),"review again"));await f.Db.SaveChangesAsync();Assert.Equal(2,await f.Db.Set<StatementLink>().CountAsync(x=>x.UserId==f.User));
    }
    [DeletionSqlFact] public async Task ImportIdentityIsStableAndBalancesUnchanged(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();var job=new ImportJob{UserId=f.User,SourceHash="synthetic-sha",State="Preview"};
        var data=JsonSerializer.Serialize(new{accountId=a.Id,currency="CNY",amount="10.00",occurredAt="2026-10-01T12:00:00+08:00",type="Expense",merchant="Synthetic",note="",externalId="bank-1"});
        f.Db.Add(job);f.Db.Add(new ImportRow{UserId=f.User,ImportJobId=job.Id,Index=1,DataJson=data});await f.Db.SaveChangesAsync();
        var first=Json(await f.Service.ImportStatements(f.User,new(job.Id,a.Id,"1")));await f.Db.SaveChangesAsync();Assert.Equal(1,first.GetProperty("imported").GetInt32());
        var again=Json(await f.Service.ImportStatements(f.User,new(job.Id,a.Id,"1")));Assert.Equal(1,again.GetProperty("duplicates").GetInt32());Assert.Equal(1000,await f.Service.Balance(f.User,a.Id));
        Assert.Empty(await f.Db.Transactions.Where(t=>t.UserId==f.User).ToArrayAsync());
    }
    [DeletionSqlFact] public async Task RefundCardRepaymentAndMultiplePaymentSourcesConfirmOnlyExistingLedgerFacts(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();var b=f.Account();b.Name="合成信用卡";b.Type="CreditCard";var original=f.Expense(a);original.OccurredAt=DateTimeOffset.UtcNow.AddDays(-2);
        var refund=new FinanceTransaction{UserId=f.User,Type="Refund",AccountId=a.Id,OriginalTransactionId=original.Id,Amount=4,Currency="CNY",Merchant="历史商户",OccurredAt=original.OccurredAt.AddHours(1)};
        refund.Entries.Add(new(){UserId=f.User,Kind="Account",AccountId=a.Id,Amount=4,BaseAmount=4});refund.Entries.Add(new(){UserId=f.User,Kind="Expense",CategoryId=original.CategoryId,Amount=-4,BaseAmount=-4});f.Db.Add(refund);
        var repayment=f.Expense(a);repayment.Type="CreditCardPayment";repayment.ToAccountId=b.Id;repayment.Entries.RemoveAll(e=>e.Kind=="Expense");repayment.Entries.Add(new(){UserId=f.User,Kind="Account",AccountId=b.Id,Amount=10,BaseAmount=10});
        var split=f.Expense(a);split.Entries.Single(e=>e.Kind=="Account").Amount=-4;split.Entries.Single(e=>e.Kind=="Account").BaseAmount=-4;split.Entries.Add(new(){UserId=f.User,Kind="Account",AccountId=b.Id,Amount=-6,BaseAmount=-6});
        var job=new ImportJob{UserId=f.User};var source=new ImportRow{UserId=f.User,ImportJobId=job.Id};f.Db.AddRange(job,source);await f.Db.SaveChangesAsync();
        async Task Match(FinanceTransaction tx,Account account,decimal amount,string type){var row=Row(f,account,job,source);row.Amount=amount;row.Type=type;row.OccurredAt=tx.OccurredAt;f.Db.Add(row);await f.Db.SaveChangesAsync();var candidate=Json(await f.Service.StatementCandidates(f.User,row.Id)).GetProperty("candidates").EnumerateArray().Single(x=>x.GetProperty("transactionId").GetString()==tx.Id);Assert.NotEqual("Conflict",candidate.GetProperty("confidence").GetString());await f.Service.ConfirmStatement(f.User,row.Id,new(tx.Id,row.Version.ToString(),tx.Version.ToString(),"Synthetic complex business review"));await f.Db.SaveChangesAsync();Assert.Equal("Matched",row.State);}
        var beforeA=await f.Service.Balance(f.User,a.Id);var beforeB=await f.Service.Balance(f.User,b.Id);var count=await f.Db.Entries.CountAsync(e=>e.UserId==f.User);
        await Match(refund,a,4,"Refund");await Match(repayment,a,-10,"CreditCardPayment");await Match(repayment,b,10,"CreditCardPayment");await Match(split,a,-4,"Expense");await Match(split,b,-6,"Expense");
        Assert.Equal(5,await f.Db.Set<StatementLink>().CountAsync(l=>l.UserId==f.User&&l.State=="Confirmed"));Assert.Equal(beforeA,await f.Service.Balance(f.User,a.Id));Assert.Equal(beforeB,await f.Service.Balance(f.User,b.Id));Assert.Equal(count,await f.Db.Entries.CountAsync(e=>e.UserId==f.User));
    }
    [DeletionSqlFact] public async Task UnsavedRulesPreviewFixedAmountsAndOverviewCountsWithoutWritingFacts(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();var t=f.Expense(a);var job=new ImportJob{UserId=f.User};var source=new ImportRow{UserId=f.User,ImportJobId=job.Id};f.Db.AddRange(job,source);await f.Db.SaveChangesAsync();var first=Row(f,a,job,source);var second=Row(f,a,job,source);second.OccurredAt=first.OccurredAt;f.Db.AddRange(first,second);await f.Db.SaveChangesAsync();
        var input=new StatementRuleInput(a.Id,"Unsaved amount rule","历史商户","Expense","CNY","",RequireReference:false,ExpectedAmount:"10");
        var preview=Json(await f.Service.StatementRulePreview(f.User,input));Assert.Equal(2,preview.GetProperty("evaluated").GetInt32());Assert.All(preview.GetProperty("results").EnumerateArray(),x=>Assert.Equal(1,x.GetProperty("matchingCount").GetInt32()));Assert.False(preview.GetProperty("automaticConfirmation").GetBoolean());
        var missed=Json(await f.Service.StatementRulePreview(f.User,input with{ExpectedAmount="11"}));Assert.All(missed.GetProperty("results").EnumerateArray(),x=>Assert.Equal(0,x.GetProperty("matchingCount").GetInt32()));Assert.Empty(await f.Db.Set<StatementRule>().Where(r=>r.UserId==f.User).ToArrayAsync());Assert.Equal(1,t.Version);Assert.Equal("Pending",first.State);
        var overview=Json(await f.Service.StatementOverview(f.User));Assert.Equal(2,overview.GetProperty("suspectedDuplicateCount").GetInt64());Assert.Equal(2,overview.GetProperty("manualReviewCount").GetInt32());Assert.Equal(0,overview.GetProperty("knownDifferenceCount").GetInt32());
        await f.Service.StatementAllocations(f.User,new([new(first.Id,"1",t.Id,"1","-4")],"Partial amount verified"),true);await f.Db.SaveChangesAsync();Assert.Equal(1,Json(await f.Service.StatementOverview(f.User)).GetProperty("knownDifferenceCount").GetInt32());
        var rule=Json(await f.Service.SaveStatementRule(f.User,null,input));await f.Db.SaveChangesAsync();Assert.Equal("10.00",rule.GetProperty("expectedAmount").GetString());Assert.Equal(990,await f.Service.Balance(f.User,a.Id));
    }
    [DeletionSqlFact] public async Task SourceSignsArePreservedAndAmbiguousTransfersRequireDirection(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();var job=new ImportJob{UserId=f.User,SourceHash="sign-evidence"};f.Db.Add(job);
        (string type,string amount,string direction,decimal? expected)[] cases=[("Expense","-10","",-10),("Income","-3","",-3),("Refund","-2","",-2),("Transfer","4","",null),("Transfer","4","IN",4),("Transfer","-5","",-5),("Income","-6","IN",6)];
        for(var i=0;i<cases.Length;i++){var c=cases[i];f.Db.Add(new ImportRow{UserId=f.User,ImportJobId=job.Id,Index=i+1,DataJson=JsonSerializer.Serialize(new{accountId=a.Id,currency="CNY",amount=c.amount,sourceAmount=c.amount,type=c.type,sourceType=c.type,statementDirection=c.direction,occurredAt="2026-10-20T12:00:00+08:00",merchant="Synthetic signs",externalId="sign-"+i})});}await f.Db.SaveChangesAsync();
        var result=Json(await f.Service.ImportStatements(f.User,new(job.Id,a.Id,"1")));await f.Db.SaveChangesAsync();Assert.Equal(6,result.GetProperty("imported").GetInt32());Assert.Single(result.GetProperty("failures").EnumerateArray());var rows=await f.Db.Set<StatementRecord>().Where(r=>r.UserId==f.User).ToDictionaryAsync(r=>r.Reference);for(var i=0;i<cases.Length;i++)if(cases[i].expected.HasValue)Assert.Equal(cases[i].expected,rows["sign-"+i].Amount);Assert.Equal(1000,await f.Service.Balance(f.User,a.Id));
    }
