        var job=new ImportJob{UserId=f.User};var source=new ImportRow{UserId=f.User,ImportJobId=job.Id};f.Db.AddRange(job,source);await f.Db.SaveChangesAsync();var row=Row(f,a,job,source);row.Reference=target.ExternalId;f.Db.Add(row);await f.Db.SaveChangesAsync();var result=Json(await f.Service.StatementCandidates(f.User,row.Id));Assert.True(result.GetProperty("truncated").GetBoolean());Assert.Equal(100,result.GetProperty("candidates").GetArrayLength());var candidate=result.GetProperty("candidates")[0];Assert.Equal(target.Id,candidate.GetProperty("transactionId").GetString());Assert.Contains(candidate.GetProperty("reasons").EnumerateArray(),x=>x.GetString()=="ReferenceExact");Assert.Contains(candidate.GetProperty("reasons").EnumerateArray(),x=>x.GetString()=="DateDifference");Assert.Equal(20,candidate.GetProperty("dateDeviation").GetInt32());
