    [DeletionSqlFact] public async Task CounterpartyTailIsUnverifiedWhileFullKnownMismatchBlocksConfirmation(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();var b=f.Account();b.Name="Known counterparty";b.Type="Bank";b.CardNumber="1111222233334444";b.CardLastFour="4444";var t=f.Expense(a);t.Type="Transfer";t.ToAccountId=b.Id;t.Entries.RemoveAll(e=>e.Kind=="Expense");t.Entries.Add(new(){UserId=f.User,TransactionId=t.Id,Kind="Account",AccountId=b.Id,Amount=10,BaseAmount=10});var job=new ImportJob{UserId=f.User};var source=new ImportRow{UserId=f.User,ImportJobId=job.Id};f.Db.AddRange(job,source);await f.Db.SaveChangesAsync();var partial=Row(f,a,job,source);partial.Type="Transfer";partial.CounterpartyHint="4444";partial.CounterpartyKey=FinanceService.StatementCounterpartyKey(f.User,"4444");var wrong=Row(f,a,job,source);wrong.Type="Transfer";wrong.CounterpartyHint="6666";wrong.CounterpartyKey=FinanceService.StatementCounterpartyKey(f.User,"9999888877776666");f.Db.AddRange(partial,wrong);await f.Db.SaveChangesAsync();
        var candidate=Json(await f.Service.StatementCandidates(f.User,partial.Id)).GetProperty("candidates")[0];Assert.Contains(candidate.GetProperty("reasons").EnumerateArray(),x=>x.GetString()=="CounterpartyUnverified");var mismatch=await Assert.ThrowsAsync<ApiException>(()=>f.Service.ConfirmStatement(f.User,wrong.Id,new(t.Id,"1","1","review")));Assert.Contains("对方账号",mismatch.Message);await f.Service.ConfirmStatement(f.User,partial.Id,new(t.Id,"1","1","Tail only; full reference and transfer legs reviewed"));await f.Db.SaveChangesAsync();Assert.Equal("Matched",partial.State);Assert.Equal(990,await f.Service.Balance(f.User,a.Id));
