    [DeletionSqlFact] public async Task FileRowIdentitySurvivesRemappingLegacyHashesAndIdenticalRows(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();
        string Data(string merchant)=>JsonSerializer.Serialize(new{accountId=a.Id,currency="CNY",amount="10",type="Expense",occurredAt="2026-10-01T12:00:00+08:00",merchant,externalId=""});
        async Task<ImportJob> Job(string merchant,int count=1){var job=new ImportJob{UserId=f.User,SourceHash="same-synthetic-file",State="Preview"};f.Db.Add(job);for(var i=1;i<=count;i++)f.Db.Add(new ImportRow{UserId=f.User,ImportJobId=job.Id,Index=i,DataJson=Data(merchant)});await f.Db.SaveChangesAsync();return job;}
        var first=await Job("Original");await f.Service.ImportStatements(f.User,new(first.Id,a.Id,"1"));await f.Db.SaveChangesAsync();var evidence=await f.Db.Set<StatementRecord>().SingleAsync(r=>r.UserId==f.User);var legacy=new string('D',64);evidence.IdentityHash=legacy;await f.Db.SaveChangesAsync();
        var changed=await Job("Changed mapping");var conflict=Json(await f.Service.ImportStatements(f.User,new(changed.Id,a.Id,"1")));Assert.Equal(0,conflict.GetProperty("imported").GetInt32());Assert.Single(conflict.GetProperty("failures").EnumerateArray());
        var repeat=await Job("Original",2);var received=Json(await f.Service.ImportStatements(f.User,new(repeat.Id,a.Id,"1")));await f.Db.SaveChangesAsync();Assert.Equal(1,received.GetProperty("imported").GetInt32());Assert.Equal(1,received.GetProperty("duplicates").GetInt32());var replay=Json(await f.Service.ImportStatements(f.User,new(repeat.Id,a.Id,"1")));Assert.Equal(2,replay.GetProperty("duplicates").GetInt32());Assert.Equal(2,await f.Db.Set<StatementRecord>().CountAsync(r=>r.UserId==f.User));Assert.Equal(legacy,evidence.IdentityHash);Assert.Equal(1000,await f.Service.Balance(f.User,a.Id));Assert.Empty(await f.Db.Transactions.Where(t=>t.UserId==f.User).ToArrayAsync());
    }
    [DeletionSqlFact] public async Task UnsafeAutoConfirmationCannotBeEnabled(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();await f.Db.SaveChangesAsync();
        await Assert.ThrowsAsync<ApiException>(()=>f.Service.SaveStatementRule(f.User,null,new(a.Id,"test","","","CNY","",AutoConfirm:true)));
