    [DeletionSqlFact] public async Task BalancePreviewRejectsStaleEvidenceAndStoresSnapshotOnly(){
        await using var f=new DeletionSqlTests.Fixture();await f.Initialize();var a=f.Account();var t=f.Expense(a);t.OccurredAt=DateTimeOffset.UtcNow.AddHours(-2);await f.Db.SaveChangesAsync();
        var b=new StatementBalanceInput(a.Id,t.OccurredAt.AddHours(-1),t.OccurredAt.AddHours(1),"1000","1000");
